entries[36686] = { ["name"] = "Schattenstoff", ["text"] = "Wirken in 25 sek. 3.833 tagen Abklingzeit\nReagenzien:\nMagieerfüllter Netherstoffballen , Urschatten , Urfeuer\nDie Verwandlung dieser Gegenstände in Schattenstoff kann nur am Altar der Schatten im Schattenmondtal durchgeführt werden. Zudem werden die Mächte des Altars nur hin und wieder gestatten, auf diese Weise benutzt zu werden.\nSchattenstoff" }
